DO $$
BEGIN
CREATE TEMP TABLE _t(field text,branch text,url text,note text) ON COMMIT DROP;
CREATE TEMP TABLE _v(field text,branch text,g int,course text,h int) ON COMMIT DROP;
SELECT p.effective_academic_year,p.school_type,p.program_type,t.field,t.branch,p.grade_level,p.required_course_count,p.required_hour_total,p.elective_course_min,p.elective_course_max,p.elective_hour_min,p.elective_hour_max,p.total_hour_min,p.total_hour_max,p.total_hour_target,p.group_rules,t.url,'2021-33',t.note,true,p.schedule_variant,p.common_hours,p.vocational_hours,p.elective_vocational_hours,p.elective_hours,p.guidance_hours,p.enterprise_hours,'CURRENTLY_VALID',p.parsed_constraints,p.academic_support_hours FROM official_curriculum_profiles p CROSS JOIN _t t WHERE p.active AND p.school_type='MESEM' AND p.field_name='Makine Teknolojisi' AND p.branch_name='Anahtarcılık ve Çilingirlik' AND p.source_decision_no='2021-33' ON CONFLICT DO NOTHING;
SELECT s.effective_academic_year,s.school_type,s.program_type,s.grade_level,s.course_id,s.category,s.hour_options,s.max_selections,s.repeat_across_years,s.elective_group_key,t.url,t.note,true,t.field,t.branch,s.parsed_constraints,s.school_subtype,'2021-33',s.source_decision_date,'HAFTALIK DERS ÇİZELGESİ',1,false,s.schedule_variant FROM official_course_schedule_catalog s CROSS JOIN _t t WHERE s.active AND s.field_name='Makine Teknolojisi' AND s.branch_name='Anahtarcılık ve Çilingirlik' AND s.source_decision_no='2021-33' AND (s.category='zorunlu' OR EXISTS(SELECT 1 FROM course_catalog c WHERE c.id=s.course_id AND c.name='İşletmelerde Mesleki Eğitim')) ON CONFLICT DO NOTHING;
SELECT '2026-2027','MESEM','MESEM',v.g,c.id,'uygulama',ARRAY[v.h],1,true,t.url,t.note,true,v.field,v.branch,'[]'::jsonb,'2021-33','HAFTALIK DERS ÇİZELGESİ',1,false,x.variant FROM _v v JOIN course_catalog c ON c.name=v.course JOIN _t t ON t.field=v.field AND t.branch=v.branch CROSS JOIN (VALUES('USTALIK'),('DIPLOMA'))x(variant) ON CONFLICT DO NOTHING;
END $$;